CREATE INDEX "gedcom_sort_order_index" on "wt_gedcom" ("sort_order");
CREATE TABLE "wt_site_setting" ("setting_name" varchar not null, "setting_value" varchar not null, primary key ("setting_name"));
CREATE TABLE "wt_gedcom_setting" ("gedcom_id" integer not null, "setting_name" varchar not null, "setting_value" varchar not null, foreign key("gedcom_id") references "wt_gedcom"("gedcom_id"), primary key ("gedcom_id", "setting_name"));
CREATE TABLE "wt_user" ("user_id" integer not null primary key autoincrement, "user_name" varchar not null, "real_name" varchar not null, "email" varchar not null, "password" varchar not null);
