CREATE TABLE "wt_user_setting" ("user_id" integer not null, "setting_name" varchar not null, "setting_value" varchar not null, foreign key("user_id") references "wt_user"("user_id"), primary key ("user_id", "setting_name"));
CREATE TABLE "wt_user_gedcom_setting" ("user_id" integer not null, "gedcom_id" integer not null, "setting_name" varchar not null, "setting_value" varchar not null, foreign key("user_id") references "wt_user"("user_id"), foreign key("gedcom_id") references "wt_gedcom"("gedcom_id"), primary key ("user_id", "gedcom_id", "setting_name"));
