CREATE TABLE "wt_log" ("log_id" integer not null primary key autoincrement, "log_time" datetime default CURRENT_TIMESTAMP not null, "log_type" varchar check ("log_type" in ('auth', 'config', 'debug', 'edit', 'error', 'media', 'search')) not null, "log_message" text not null, "ip_address" varchar not null, "user_id" integer, "gedcom_id" integer, foreign key("user_id") references "wt_user"("user_id"), foreign key("gedcom_id") references "wt_gedcom"("gedcom_id"));
CREATE INDEX "log_log_time_index" on "wt_log" ("log_time");
CREATE INDEX "log_log_type_index" on "wt_log" ("log_type");
CREATE INDEX "log_ip_address_index" on "wt_log" ("ip_address");
CREATE INDEX "log_user_id_index" on "wt_log" ("user_id");
CREATE INDEX "log_gedcom_id_index" on "wt_log" ("gedcom_id");
CREATE TABLE "wt_change" ("change_id" integer not null primary key autoincrement, "change_time" datetime default CURRENT_TIMESTAMP not null, "status" varchar check ("status" in ('accepted', 'pending', 'rejected')) not null default 'pending', "gedcom_id" integer not null, "xref" varchar not null, "old_gedcom" text not null, "new_gedcom" text not null, "user_id" integer not null, foreign key("user_id") references "wt_user"("user_id"), foreign key("gedcom_id") references "wt_gedcom"("gedcom_id"));
