CREATE TABLE "wt_message" ("message_id" integer not null primary key autoincrement, "sender" varchar not null, "ip_address" varchar not null, "user_id" integer not null, "subject" varchar not null, "body" text not null, "created" datetime default CURRENT_TIMESTAMP not null, foreign key("user_id") references "wt_user"("user_id"));
