CREATE TABLE "wt_default_resn" ("default_resn_id" integer not null primary key autoincrement, "gedcom_id" integer not null, "xref" varchar, "tag_type" varchar, "resn" varchar check ("resn" in ('none', 'privacy', 'confidential', 'hidden')) not null, "comment" varchar, "updated" datetime default CURRENT_TIMESTAMP not null, foreign key("gedcom_id") references "wt_gedcom"("gedcom_id"));
